// Layout must match World.hlsli FrameConstants.
struct alignas(16) FrameConstants
{
    float viewProj[16];
    float invViewProj[16];
    float shadowViewProj[2][16];
    float cameraPos[4];
    float sunDir[4];
    float sunColor[4];
    float fogColor[4];
    float fogParams[4];
    float zenithColor[4];
    float groundColor[4];
    float terrainParams[4];
    float layerTiling[4];
    float shadowParams[2][4];
    float sh[9][4];
    float lightDir[3][4];
    float lightColor[3][4];
    float features[4];
    float layerParams[4][4];
    float terrainShading[4];
};

struct alignas(16) DrawConstants
{
    float world[16];
    float baseColor[4];
    float drawParams[4]; // x textured, y opacity, z character, w ORM map
    float material[4];   // x normal scale (0 = none), y roughness, z metallic, w occlusion strength
    float normalFlip[4]; // x +1 / -1 (normal_flip_y)
    float emissive[4];   // rgb factor, w emissive map (0/1)
    float alphaTest[4];  // x cutoff (0 = opaque), y alpha-to-coverage (0/1)
};

struct alignas(16) BoneConstants
{
    float bones[kMaxBones][16];
};

struct alignas(16) DecalConstants
{
    float center[4];
    float axisU[4];
    float axisV[4];
    float color[4];
    float mode[4];
};

struct alignas(16) PassConstants
{
    float pass[4];
};

